#!/bin/bash
# 2026-11-26: full chain for one boxC snapshot: FoF + dashboard mags (mags_only.py) -> extract.py -> mock photometry (5 survey variants x 3 axes)
# usage (inside a 1-node allocation): run_iter.sh <iter>
it=$1; I=$(printf %07d $it)
module load cray-python/3.11.7 PrgEnv-gnu cray-hdf5-parallel >/dev/null 2>&1; . /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/analysis/pyenv/bin/activate
export FOF_DYABLO=/lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/analysis/dyablo_tools/dyablo_fof/fof
[ -s /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/boxC_mags_iter$I.txt ] || OMP_NUM_THREADS=16 python -I -W ignore /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/mags_only.py /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxC_h2_eps0.03n0.5c0.1_mech_snx2_ssp300 $it /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/boxC_mags_iter$I.txt | grep -E "wrote|rror"
[ -s /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/lfpp/boxC_iter$I.npz ] || OMP_NUM_THREADS=16 python -I -W ignore /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/lfpp/extract.py /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxC_h2_eps0.03n0.5c0.1_mech_snx2_ssp300 $it /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/lfpp/boxC_iter$I.npz | grep -E "wrote|rror"
export OMP_NUM_THREADS=1 OPENBLAS_NUM_THREADS=1
for s in CEERS JADES GLIMPSE GLIMPSE_mu5 GLIMPSE_mu20; do for ax in 0 1 2; do echo "$s $ax"; done; done |   xargs -P 15 -n 2 sh -c 'python -I -W ignore /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/lfpp/mock_phot.py /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/lfpp/boxC_iter'$I'.npz $0 $1 /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/lfpp/mock/boxC_'$I'_$0_ax$1 > /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/lfpp/mock/boxC_'$I'_$0_ax$1.log 2>&1'
echo "mock logs with 'wrote': $(grep -l wrote /lustre/orion/ast031/proj-shared/pocvirk/CoDaIII/prod_sr/pocvirk/dyablo/28102026/runs/reio_v2/boxsize/lfpp/mock/boxC_${I}_*.log | wc -l) / 15"
